def pmf_of(space, X):
    """The pmf of X as {value: chance}.
    space maps each outcome to its chance.
    X gives each outcome a number."""
    if any(p < 0 for p in space.values()):
        raise ValueError("a chance is negative")
    if abs(sum(space.values()) - 1) > 1e-9:
        raise ValueError("the chances do not add up to 1")
    pmf = {}
    for outcome, p in space.items():
        if p > 0:  # an outcome of chance 0 adds no value
            x = X(outcome)
            pmf[x] = pmf.get(x, 0) + p  # outcomes that share a value add
    return pmf
